# Team Maturity Levels and Continuous Improvement (JSON)
{
  "team_maturity_model": {
    "stage_1_forming": {
      "duration": "Weeks 1-4",
      "characteristics": [
        "Roles and responsibilities being defined",
        "Testing team dynamics",
        "Learning Scrum practices",
        "High uncertainty"
      ],
      "team_health_score": 2,
      "velocity": "Unpredictable",
      "improvements_per_sprint": "1-2",
      "focus": "Establishing foundations"
    },

    "stage_2_storming": {
      "duration": "Weeks 5-12",
      "characteristics": [
        "Interpersonal conflicts emerge",
        "Process resistance (especially from senior members)",
        "Velocity still variable",
        "Increased frustration"
      ],
      "team_health_score": 3,
      "velocity": "Stabilizing",
      "improvements_per_sprint": "2-3",
      "focus": "Working through conflicts",
      "leader_role": "Facilitate difficult conversations"
    },

    "stage_3_norming": {
      "duration": "Weeks 13-24",
      "characteristics": [
        "Agreements on working practices",
        "Velocity becomes predictable",
        "Improved collaboration",
        "Psychological safety emerging"
      ],
      "team_health_score": 4,
      "velocity": "Consistent",
      "improvements_per_sprint": "3-4",
      "focus": "Optimizing practices"
    },

    "stage_4_performing": {
      "duration": "Week 25+",
      "characteristics": [
        "High autonomy and ownership",
        "Velocity consistently high",
        "Quality metrics strong",
        "Innovation happening naturally"
      ],
      "team_health_score": 5,
      "velocity": "High and stable",
      "improvements_per_sprint": "4-6",
      "focus": "Innovation and scaling"
    }
  },

  "continuous_improvement_cycle": {
    "sprint_retrospective": {
      "duration": "1.5 hours",
      "frequency": "Every 2 weeks",
      "format": "What went well, what to improve, action items",
      "outcome": "1-3 improvements to try next sprint"
    },

    "improvement_experiment": {
      "example_1": {
        "improvement": "Daily standup shortened from 20 to 15 minutes",
        "metric": "Time saved per sprint",
        "result": "5 hours saved, no loss of communication"
      },
      "example_2": {
        "improvement": "Pair programming on complex features",
        "metric": "Bug detection rate and team knowledge sharing",
        "result": "60% fewer bugs, faster onboarding"
      },
      "example_3": {
        "improvement": "Automated testing investment",
        "metric": "Test execution time and defect escape rate",
        "result": "90% faster tests, 80% fewer production bugs"
      }
    },

    "measurement": {
      "velocity_trend": "Track stability and growth",
      "quality_metrics": "Bug count, test coverage",
      "team_satisfaction": "Quarterly surveys",
      "process_metrics": "Sprint goal achievement rate"
    }
  }
}
